using System.Collections.Generic;
using System.Text;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.Controls;

/// <summary>
/// Bluetooth controller connection/input diagnostics for the Unity Input System.
///
/// This component installs itself after a scene is loaded, so no scene setup is
/// required. It reports how Unity classified a controller and prints the actual
/// control paths generated by its buttons and sticks.
/// </summary>
public sealed class ControllerConnectionDiagnostics : MonoBehaviour
{
    public static ControllerConnectionDiagnostics Instance { get; private set; }

    private const float AxisDeadzone = 0.20f;
    private const float AxisLogDelta = 0.15f;
    private const float AxisLogInterval = 0.15f;

    private readonly Dictionary<InputControl, bool> buttonStates =
        new Dictionary<InputControl, bool>();
    private readonly Dictionary<InputControl, Vector2> vectorStates =
        new Dictionary<InputControl, Vector2>();
    private readonly Dictionary<InputControl, float> axisStates =
        new Dictionary<InputControl, float>();

    private string lastInput = "No controller input yet";
    private float nextAxisLogTime;
    private readonly Queue<string> recentLogs = new Queue<string>();

    public bool ShowOverlay { get; set; }
    public string LastInput => lastInput;
    public Vector2 StickValue { get; private set; }
    public bool Connected { get; private set; }
    public string DeviceSummary { get; private set; } = "No controller detected";
    public IEnumerable<string> RecentLogs => recentLogs;

    public bool SouthPressed => Gamepad.current != null && Gamepad.current.buttonSouth.isPressed;
    public bool NorthPressed => Gamepad.current != null && Gamepad.current.buttonNorth.isPressed;
    public bool WestPressed => Gamepad.current != null && Gamepad.current.buttonWest.isPressed;
    public bool EastPressed => Gamepad.current != null && Gamepad.current.buttonEast.isPressed;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    private static void Install()
    {
        if (FindAnyObjectByType<ControllerConnectionDiagnostics>() != null) return;

        GameObject diagnostics = new GameObject("Controller Connection Diagnostics");
        DontDestroyOnLoad(diagnostics);
        diagnostics.AddComponent<ControllerConnectionDiagnostics>();
    }

    private void OnEnable()
    {
        Instance = this;
        InputSystem.onDeviceChange += OnDeviceChange;
        RebuildState();
        LogDeviceInventory("startup scan");
    }

    private void OnDisable()
    {
        InputSystem.onDeviceChange -= OnDeviceChange;
        if (Instance == this) Instance = null;
    }

    private void OnDeviceChange(InputDevice device, InputDeviceChange change)
    {
        string message = $"[Controller] device {change}: {Describe(device)}";
        Debug.Log(message);
        lastInput = message;

        RebuildState();

        if (change == InputDeviceChange.Added ||
            change == InputDeviceChange.Reconnected ||
            change == InputDeviceChange.Enabled ||
            change == InputDeviceChange.ConfigurationChanged)
        {
            LogControls(device);
        }
    }

    private void Update()
    {
        Connected = false;
        DeviceSummary = "No controller detected";
        StickValue = Vector2.zero;

        foreach (InputDevice device in InputSystem.devices)
        {
            if (!IsControllerCandidate(device)) continue;

            if (!Connected)
            {
                Connected = true;
                DeviceSummary = Describe(device);
            }

            Gamepad gamepad = device as Gamepad;
            if (gamepad != null) StickValue = gamepad.leftStick.ReadValue();
            else
            {
                Joystick joystick = device as Joystick;
                if (joystick != null) StickValue = joystick.stick.ReadValue();
            }

            foreach (InputControl control in device.allControls)
            {
                ButtonControl button = control as ButtonControl;
                if (button != null)
                {
                    bool wasPressed;
                    buttonStates.TryGetValue(control, out wasPressed);
                    bool isPressed = button.isPressed;
                    buttonStates[control] = isPressed;

                    if (isPressed && !wasPressed)
                        ReportInput(device, control, "pressed");

                    continue;
                }

                Vector2Control vector = control as Vector2Control;
                if (vector != null)
                {
                    Vector2 previous;
                    vectorStates.TryGetValue(control, out previous);
                    Vector2 value = vector.ReadValue();
                    vectorStates[control] = value;

                    if (Time.unscaledTime >= nextAxisLogTime &&
                        value.magnitude >= AxisDeadzone &&
                        Vector2.Distance(previous, value) >= AxisLogDelta)
                    {
                        nextAxisLogTime = Time.unscaledTime + AxisLogInterval;
                        ReportInput(device, control, $"value=({value.x:F2}, {value.y:F2})");
                    }

                    continue;
                }

                AxisControl axis = control as AxisControl;
                if (axis == null || control.parent is Vector2Control) continue;

                float previousAxis;
                axisStates.TryGetValue(control, out previousAxis);
                float axisValue = axis.ReadValue();
                axisStates[control] = axisValue;

                if (Time.unscaledTime >= nextAxisLogTime &&
                    Mathf.Abs(axisValue) >= AxisDeadzone &&
                    Mathf.Abs(axisValue - previousAxis) >= AxisLogDelta)
                {
                    nextAxisLogTime = Time.unscaledTime + AxisLogInterval;
                    ReportInput(device, control, $"value={axisValue:F2}");
                }
            }
        }
    }

    private void OnGUI()
    {
        if (!ShowOverlay) return;

        const float width = 620f;
        float height = Mathf.Min(Screen.height - 20f, 300f);

        GUI.depth = -1000;
        GUILayout.BeginArea(new Rect(10f, 10f, width, height), GUI.skin.box);
        GUILayout.Label("CONTROLLER DIAGNOSTICS");

        int count = 0;
        foreach (InputDevice device in InputSystem.devices)
        {
            if (!IsControllerCandidate(device)) continue;
            count++;
            GUILayout.Label(Describe(device));
        }

        if (count == 0)
            GUILayout.Label("No Gamepad / Joystick / controller-like HID detected");

        GUILayout.Space(6f);
        GUILayout.Label("Last input:");
        GUILayout.Label(lastInput);
        GUILayout.EndArea();
    }

    private void RebuildState()
    {
        buttonStates.Clear();
        vectorStates.Clear();
        axisStates.Clear();

        foreach (InputDevice device in InputSystem.devices)
        {
            if (!IsControllerCandidate(device)) continue;

            foreach (InputControl control in device.allControls)
            {
                ButtonControl button = control as ButtonControl;
                if (button != null)
                {
                    buttonStates[control] = button.isPressed;
                    continue;
                }

                Vector2Control vector = control as Vector2Control;
                if (vector != null)
                {
                    vectorStates[control] = vector.ReadValue();
                    continue;
                }

                AxisControl axis = control as AxisControl;
                if (axis != null && !(control.parent is Vector2Control))
                    axisStates[control] = axis.ReadValue();
            }
        }
    }

    private void LogDeviceInventory(string reason)
    {
        int count = 0;
        foreach (InputDevice device in InputSystem.devices)
        {
            if (!IsControllerCandidate(device)) continue;
            count++;
            Debug.Log($"[Controller] {reason}: {Describe(device)}");
            LogControls(device);
        }

        if (count == 0)
            Debug.Log("[Controller] No Gamepad / Joystick / controller-like HID detected.");
    }

    private static void LogControls(InputDevice device)
    {
        StringBuilder controls = new StringBuilder();
        foreach (InputControl control in device.allControls)
        {
            if (!(control is ButtonControl) &&
                !(control is Vector2Control) &&
                !(control is AxisControl))
                continue;

            if (controls.Length > 0) controls.Append(", ");
            controls.Append(control.path);
        }

        Debug.Log($"[Controller] controls for {device.displayName}: {controls}");
    }

    private void ReportInput(InputDevice device, InputControl control, string value)
    {
        lastInput = $"{device.displayName}  {control.path}  {value}";
        recentLogs.Enqueue(lastInput);
        while (recentLogs.Count > 8) recentLogs.Dequeue();
        Debug.Log("[Controller] " + lastInput);
    }

    private static bool IsControllerCandidate(InputDevice device)
    {
        if (device is Gamepad || device is Joystick) return true;

        if (device.description.interfaceName != "HID") return false;

        bool hasButton = false;
        bool hasAxis = false;
        foreach (InputControl control in device.allControls)
        {
            if (control is ButtonControl) hasButton = true;
            if (control is AxisControl || control is Vector2Control) hasAxis = true;
        }

        return hasButton && hasAxis;
    }

    private static string Describe(InputDevice device)
    {
        string type = device is Gamepad ? "Gamepad" :
                      device is Joystick ? "Joystick" : device.layout;

        return $"id={device.deviceId} type={type} layout={device.layout} " +
               $"name={device.displayName} interface={device.description.interfaceName} " +
               $"manufacturer={device.description.manufacturer} product={device.description.product}";
    }
}
